/** 地方の範囲の輪（緯度経度の一覧）の一覧。島が多い地方は輪が多い */
export function regionRings(id: RegionId): { lat: number; lng: number }[][] {
  return SHAPES[id].map((flat) => {
    const ring: { lat: number; lng: number }[] = []
    for (let i = 0; i + 1 < flat.length; i += 2) ring.push({ lat: flat[i], lng: flat[i + 1] })
    return ring
  })
}
